INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('8b81a645-306d-4cc1-962a-ab597d640fe5', 'advanced', 'multiple_choice', 'A merchandiser''s OTB (Open-To-Buy) budget for next month shows: Planned sales $450,000, Planned markdowns $35,000, Planned end-of-month stock $620,000, Beginning-of-month stock $580,000, and stock already on order $180,000. Using OTB = (Planned Sales + Planned Markdowns + Planned EOM Stock) − Beginning Stock − On-Order Stock, what is the remaining OTB?', '["OTB = ($450,000+$35,000+$620,000)−$580,000−$180,000 = $1,105,000−$760,000 = $345,000 remaining available to spend","OTB = $450,000−$35,000−$620,000+$580,000+$180,000 = a fundamentally different (and incorrect) sign arrangement of the same terms, illustrating why the exact formula structure (which terms add vs. subtract) must be applied precisely rather than approximated","OTB = $450,000 exactly, incorrectly using only the planned sales figure and ignoring all other formula components","OTB is always equal to the beginning stock figure alone, incorrectly treating one input as if it were the complete answer"]'::jsonb, 'OTB = ($450,000+$35,000+$620,000)−$580,000−$180,000 = $1,105,000−$760,000 = $345,000 remaining available to spend', 'OTB = (Planned Sales + Planned Markdowns + Planned EOM Stock) − Beginning Stock − On-Order Stock = ($450,000+$35,000+$620,000) − $580,000 − $180,000 = $1,105,000 − $760,000 = $345,000 — this directly applies the earlier OTB formula/concept with real numbers, showing the merchandiser has $345,000 of additional PLANNED inventory budget still available to commit to new purchase orders this month before exceeding the planned stock/sales targets, a genuine practical application of the OTB discipline discussed earlier as central to avoiding both overbuying and underbuying.', 3, '{"OTB-calculation"}'::text[]),
('8b81a645-306d-4cc1-962a-ab597d640fe5', 'advanced', 'multiple_choice', 'A retail buyer calculates that Style A (bought at $12/unit, sold at $30/unit) has a 60% margin, while Style B (bought at $8/unit, sold at $22/unit) has a margin of approximately 63.6%. Despite Style B''s HIGHER margin percentage, the buyer chooses to allocate MORE OTB budget to Style A. Using the earlier GMROI concept, under what condition would this be the financially SOUND decision rather than a mistake?', '["This decision is always a mistake regardless of any other factor, since margin percentage alone should always be the sole determining factor in OTB budget allocation decisions with zero exception","If Style A has a demonstrated FASTER sell-through/inventory turnover rate than Style B (e.g., Style A sells through in 4 weeks versus Style B''s 10 weeks), Style A''s GMROI (combining margin AND turnover, as established earlier) could genuinely EXCEED Style B''s GMROI despite Style A''s lower raw margin percentage — since GMROI, not margin percentage alone, is the more complete measure of which style generates better RETURN on the inventory capital invested, prioritizing the higher-GMROI style (even with lower margin%) can be the financially sound decision","Margin percentage and GMROI always produce identical style rankings, making it mathematically impossible for a lower-margin style to ever show better GMROI than a higher-margin style under any turnover scenario","GMROI is only relevant for very large retail chains, making this concept technically inapplicable to a single buyer''s individual OTB allocation decision between two specific styles"]'::jsonb, 'If Style A has a demonstrated FASTER sell-through/inventory turnover rate than Style B (e.g., Style A sells through in 4 weeks versus Style B''s 10 weeks), Style A''s GMROI (combining margin AND turnover, as established earlier) could genuinely EXCEED Style B''s GMROI despite Style A''s lower raw margin percentage — since GMROI, not margin percentage alone, is the more complete measure of which style generates better RETURN on the inventory capital invested, prioritizing the higher-GMROI style (even with lower margin%) can be the financially sound decision', 'This directly applies the earlier GMROI concept (combining margin AND inventory turnover into one return-on-investment measure) to a real OTB allocation decision — margin PERCENTAGE alone doesn''t capture how efficiently invested capital converts to return over TIME; if Style A turns over significantly faster than Style B, its GMROI (margin × turnover rate) can genuinely exceed Style B''s despite Style A''s lower raw margin percentage, meaning the buyer''s decision to favor Style A isn''t necessarily a mistake — it could reflect sound GMROI-based reasoning that a simple margin-percentage comparison alone would miss, directly reinforcing the earlier lesson that margin percentage alone is an incomplete basis for inventory investment prioritization decisions.', 3, '{"GMROI-vs-margin-percentage-decision"}'::text[]);
COMMIT;
